//! TypeScript emitter: one `interface` or `type` per schema, types only.

use crate::schema::{Def, Lit, Object, Ty, Variant};

const WIDTH: usize = 120;

pub fn render(defs: &[Def]) -> String {
    let mut out = String::from(
        "// Generated by `cargo xtask contracts` from docs/api/openapi.json. Do not edit.\n\
         // Types only: nothing here exists at runtime.\n",
    );
    for d in defs {
        out.push('\n');
        if let Some(doc) = &d.doc {
            out.push_str(&doc_comment(doc, 0));
        }
        match &d.ty {
            Ty::Object(o) if matches!(o.extra.as_deref(), None | Some(Ty::Unknown)) => {
                out.push_str(&format!("export interface {} {}\n", d.name, object(o, 0)));
            }
            t => {
                let body = ty(t, 0, d.name.len() + 14, false);
                out.push_str(&join(&format!("export type {} =", d.name), &body));
                out.push_str(";\n");
            }
        }
    }
    out
}

fn join(prefix: &str, body: &str) -> String {
    if body.starts_with('\n') { format!("{prefix}{body}") } else { format!("{prefix} {body}") }
}

fn doc_comment(text: &str, ind: usize) -> String {
    let pad = " ".repeat(ind);
    let text = text.replace("*/", "*\\/");
    let lines: Vec<&str> = text.lines().map(str::trim_end).collect();
    if lines.len() == 1 && ind + lines[0].len() + 8 <= WIDTH {
        return format!("{pad}/** {} */\n", lines[0]);
    }
    let mut s = format!("{pad}/**\n");
    for l in lines {
        if l.is_empty() {
            s.push_str(&format!("{pad} *\n"));
        } else {
            s.push_str(&format!("{pad} * {l}\n"));
        }
    }
    s.push_str(&format!("{pad} */\n"));
    s
}

fn prop_name(name: &str) -> String {
    let mut chars = name.chars();
    let ok = chars.next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$');
    if ok { name.to_string() } else { serde_json::to_string(name).unwrap_or_default() }
}

fn lit(l: &Lit) -> String {
    match l {
        Lit::Str(s) => serde_json::to_string(s).unwrap_or_default(),
        Lit::Num(n) => n.clone(),
        Lit::Bool(b) => b.to_string(),
    }
}

/// `{ ... }` with its closing brace at `ind`.
fn object(o: &Object, ind: usize) -> String {
    let pad = " ".repeat(ind + 2);
    if o.fields.is_empty() && o.extra.is_none() {
        return "{ [key: string]: never }".to_string();
    }
    let mut s = String::from("{\n");
    for f in &o.fields {
        if let Some(doc) = &f.doc {
            s.push_str(&doc_comment(doc, ind + 2));
        }
        let prefix = format!("{pad}{}{}:", prop_name(&f.name), if f.required { "" } else { "?" });
        let body = ty(&f.ty, ind + 2, prefix.len() + 1, false);
        s.push_str(&join(&prefix, &body));
        s.push_str(";\n");
    }
    if matches!(o.extra.as_deref(), Some(Ty::Unknown)) {
        s.push_str(&format!("{pad}[key: string]: unknown;\n"));
    }
    s.push_str(&" ".repeat(ind));
    s.push('}');
    s
}

/// `col` is where the text starts on its line (for the width check); `flat` keeps unions on one line.
fn ty(t: &Ty, ind: usize, col: usize, flat: bool) -> String {
    match t {
        Ty::Unknown => "unknown".into(),
        Ty::Never => "never".into(),
        Ty::Null => "null".into(),
        Ty::Str => "string".into(),
        Ty::Int | Ty::Num => "number".into(),
        Ty::Bool => "boolean".into(),
        Ty::Ref(n) => n.clone(),
        Ty::Lit(l) => lit(l),
        Ty::Array(inner) => {
            let s = ty(inner, ind, col, true);
            if matches!(**inner, Ty::Union(_) | Ty::Inter(_)) { format!("({s})[]") } else { format!("{s}[]") }
        }
        Ty::Tuple(items) => {
            format!("[{}]", items.iter().map(|i| ty(i, ind, col, true)).collect::<Vec<_>>().join(", "))
        }
        Ty::Map(v) => format!("{{ [key: string]: {} }}", ty(v, ind, col, true)),
        Ty::Object(o) => match o.extra.as_deref() {
            Some(e) if *e != Ty::Unknown => {
                let plain = Object { fields: o.fields.clone(), extra: None };
                format!("{} & {{ [key: string]: {} }}", object(&plain, ind), ty(e, ind, col, true))
            }
            _ => object(o, ind),
        },
        Ty::Inter(parts) => parts
            .iter()
            .map(|p| {
                let s = ty(p, ind, col, true);
                if matches!(p, Ty::Union(_)) { format!("({s})") } else { s }
            })
            .collect::<Vec<_>>()
            .join(" & "),
        Ty::Union(variants) => union(variants, ind, col, flat),
    }
}

fn union(variants: &[Variant], ind: usize, col: usize, flat: bool) -> String {
    let has_doc = variants.iter().any(|v| v.doc.is_some());
    let one_line = variants.iter().map(|v| ty(&v.ty, ind, col, true)).collect::<Vec<_>>().join(" | ");
    if flat || (!has_doc && !one_line.contains('\n') && col + one_line.len() <= WIDTH) {
        return one_line;
    }
    let pad = " ".repeat(ind + 2);
    let mut s = String::new();
    for v in variants {
        s.push('\n');
        if let Some(doc) = &v.doc {
            s.push_str(&doc_comment(doc, ind + 2));
        }
        s.push_str(&format!("{pad}| {}", ty(&v.ty, ind + 4, ind + 4, false)));
    }
    s
}
